using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchive now writes UTF-8 by default
        // (sets the EFS General Purpose Bit Flag). The legacy Java consumer
        // expects Shift-JIS encoded filenames, so specify the encoding explicitly.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("Shift-JIS");

        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: [FromKeyedServices("cache")] now throws
// InvalidOperationException if the service is not registered as keyed.
// Register with a matching key.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

